export function freshGarage(){return {version:1,credits:1800,owned:['yayla'],selected:'yayla',races:0,driverName:'Sen',customizations:{}};}
export function readGarage(storage){try{const v=JSON.parse(storage.getItem('artvin-garage-v1'));if(!v||v.version!==1)return freshGarage();const owned=CARS.filter(c=>c.id==='yayla'||v.owned?.includes(c.id)).map(c=>c.id);return {version:1,credits:Number.isFinite(v.credits)?Math.max(0,Math.floor(v.credits)):1800,owned,selected:owned.includes(v.selected)?v.selected:'yayla',races:Math.max(0,Math.floor(v.races)||0),driverName:typeof v.driverName==='string'?v.driverName.slice(0,20):'Sen',customizations:v.customizations&&typeof v.customizations==='object'&&!Array.isArray(v.customizations)?v.customizations:{}};}catch{return freshGarage();}}
export function buyVehicle(save,id){const car=CARS.find(c=>c.id===id);if(!car)throw Error('Araç bulunamadı.');if(save.owned.includes(id))return {...save,selected:id};if(save.credits<car.price)throw Error(`${car.price-save.credits} jeton daha gerekiyor. Yarışı bitirerek kazanabilirsin.`);return {...save,credits:save.credits-car.price,owned:[...save.owned,id],selected:id};}
export function raceReward(rank,crashes,topKmh){return Math.max(200,[700,500,350,250][Math.min(3,Math.max(0,rank-1))]+Math.floor(Math.min(topKmh,300)/3)-Math.min(crashes,10)*15);}
